create extension if not exists "pgcrypto";
create type public.user_role as enum ('admin','customer');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.user_role not null default 'customer', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, published boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, short_description text, description text, price numeric(12,0) not null check(price>=0), compare_at_price numeric(12,0) check(compare_at_price>=0), stock integer not null default 0 check(stock>=0), category_id uuid references public.categories(id) on delete set null, published boolean not null default false, featured boolean not null default false, is_new boolean not null default false, on_sale boolean not null default false, is_unique boolean not null default false, customizable boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create table public.product_images (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, storage_path text not null unique, public_url text not null, alt_text text, sort_order integer not null default 0, is_cover boolean not null default false, created_at timestamptz not null default now());
create table public.product_variants (id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete cascade, name text not null, value text not null, stock integer check(stock>=0), price_adjustment numeric(12,0) not null default 0, sort_order integer not null default 0, created_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), customer_name text not null, phone text not null, city text not null, address text, notes text, total numeric(12,0) not null default 0, status text not null default 'whatsapp', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, variant text, quantity integer not null check(quantity>0), unit_price numeric(12,0) not null, created_at timestamptz not null default now());
create table public.custom_requests (id uuid primary key default gen_random_uuid(), name text not null, phone text not null, product_type text, colors text, size text, initials text, description text not null, budget numeric(12,0), reference_path text, status text not null default 'new', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.gallery (id uuid primary key default gen_random_uuid(), storage_path text not null unique, public_url text not null, alt_text text, kind text, published boolean not null default true, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.testimonials (id uuid primary key default gen_random_uuid(), name text not null, comment text not null, rating integer not null default 5 check(rating between 1 and 5), photo_url text, published boolean not null default false, sort_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.store_settings (id smallint primary key default 1 check(id=1), store_name text not null default 'CAMARI', slogan text not null default 'Arte hecho para conectar.', whatsapp text not null default '', instagram text, tiktok text, facebook text, email text, logo_url text, banner_url text, about_text text, shipping_info text, contact_info text, updated_at timestamptz not null default now());
create index products_published_idx on public.products(published,created_at desc) where deleted_at is null; create index products_category_idx on public.products(category_id); create index product_images_product_idx on public.product_images(product_id,sort_order); create index variants_product_idx on public.product_variants(product_id,sort_order);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.store_settings(id) values(1) on conflict do nothing;
